UPDATE video_status_consumed_event
SET consumer_retry_count = GREATEST(
        consumer_retry_count,
        #{attempt}
    ),
    last_attempt_at = NOW(3),
    last_error = #{lastError}
WHERE event_id = #{eventId}
  AND process_status = 0

UPDATE video_status_consumed_event
SET process_status = 3,
    last_attempt_at = NOW(3),
    last_error = #{lastError}
WHERE event_id = #{eventId}
  AND process_status = #{expectedStatus}

UPDATE video_status_consumed_event
SET last_attempt_at = NOW(3),
    last_error = #{resolution}
WHERE event_id = #{eventId}
  AND process_status = 3

mapper.select:
SELECT

FROM video_status_consumed_event
WHERE process_status = 3

    AND id > #{afterId}

ORDER BY id
LIMIT #{limit}
